        const u = i / 40;
        const x = c0[0] + R * (0.2 + u * 2.2 + Math.sin(u * 3 + s * 0.6) * 0.12 + off * (1 - u) * 0.3);
        const y = c0[1] + R * (-0.15 - u * 1.25 + off * 0.6 + Math.cos(u * 2.4 + 0.5) * 0.12);
